export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const
export const MAX_SEED = 2147483646
export const MAX_MOVES = 999999
export const MAX_ELAPSED_MS = 359999999
export const MISMATCH_MS = 800

export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const

export type BoardSize = (typeof BOARD_SIZES)[number]
export type SelectionKind = (typeof SELECTION_KINDS)[keyof typeof SELECTION_KINDS]
export type Board = Readonly<{
  code: string
  size: BoardSize
  seed: number
  deck: readonly number[]
}>
export type Selection =
  | Readonly<{ kind: typeof SELECTION_KINDS.closed }>
  | Readonly<{ kind: typeof SELECTION_KINDS.one; index: number }>
  | Readonly<{ kind: typeof SELECTION_KINDS.mismatch; first: number; second: number; remainingMs: number }>
export type GameState = Readonly<{
  board: Board
  matched: readonly number[]
  selection: Selection
  moves: number
  elapsedMs: number
  started: boolean
}>
import { BOARD_SIZES, MAX_SEED, type Board, type BoardSize } from './model.ts'

const MODULUS = 2147483647
const MULTIPLIER = 16807
const RANGE = 2147483646

export function parseBoardCode(code: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code)
  const sizeText = match?.[1]
  const seedText = match?.[2]
  if (match === null || match[0] !== code || sizeText === undefined || seedText === undefined) return null
  const size = Number(sizeText)
  const seed = Number(seedText)
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null
  return Object.freeze({ code, size, seed, deck: Object.freeze(makeDeck(size, seed)) })
}

export function isBoardSize(value: number): value is BoardSize {
  return BOARD_SIZES.some((size) => size === value)
}

function makeDeck(size: BoardSize, seed: number): number[] {
  const deck: number[] = []
  for (let face = 0; face < (size * size) / 2; face += 1) deck.push(face, face)
  let state = seed
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const possible = index + 1
    const limit = Math.floor(RANGE / possible) * possible
    let x = limit
    while (x >= limit) {
      state = (state * MULTIPLIER) % MODULUS
      x = state - 1
    }
    const swapIndex = x % possible
    const current = deck[index]
    const other = deck[swapIndex]
    if (current === undefined || other === undefined) throw new Error('Invalid deck index')
    deck[index] = other
    deck[swapIndex] = current
  }
  return deck
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, SELECTION_KINDS, type GameState } from './model.ts'
import { parseBoardCode } from './board.ts'

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode)
  if (board === null) return null
  return Object.freeze({
    board,
    matched: Object.freeze([]),
    selection: Object.freeze({ kind: SELECTION_KINDS.closed }),
    moves: 0,
    elapsedMs: 0,
    started: false,
  })
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state
  if (state.matched.includes(index)) return state
  const selection = state.selection
  if (selection.kind === 'mismatch') return state
  if (selection.kind === 'closed') {
    return Object.freeze({
      ...state,
      selection: Object.freeze({ kind: SELECTION_KINDS.one, index }),
      started: true,
    })
  }
  if (index === selection.index) return state
  const nextMoves = Math.min(MAX_MOVES, state.moves + 1)
  const firstFace = state.board.deck[selection.index]
  const secondFace = state.board.deck[index]
  if (firstFace === secondFace) {
    return Object.freeze({
      ...state,
      matched: Object.freeze([...state.matched, selection.index, index]),
      selection: Object.freeze({ kind: SELECTION_KINDS.closed }),
      moves: nextMoves,
      started: true,
    })
  }
  return Object.freeze({
    ...state,
    selection: Object.freeze({ kind: SELECTION_KINDS.mismatch, first: selection.index, second: index, remainingMs: MISMATCH_MS }),
    moves: nextMoves,
    started: true,
  })
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 0 || !state.started || isWon(state)) return state
  const elapsedMs = milliseconds >= MAX_ELAPSED_MS - state.elapsedMs
    ? MAX_ELAPSED_MS
    : state.elapsedMs + milliseconds
  const selection = state.selection
  if (selection.kind !== 'mismatch') return Object.freeze({ ...state, elapsedMs })
  if (milliseconds >= selection.remainingMs) {
    return Object.freeze({ ...state, elapsedMs, selection: Object.freeze({ kind: SELECTION_KINDS.closed }) })
  }
  return Object.freeze({
    ...state,
    elapsedMs,
    selection: Object.freeze({ ...selection, remainingMs: selection.remainingMs - milliseconds }),
  })
}
import { parseBoardCode } from './board.ts'
import { advanceGame, activateCard, createGame } from './transitions.ts'
import type { GameState } from './model.ts'

const REPLAY_VERSION = 1
const MAX_REPLAY_BYTES = 1048576
const MAX_ACTIONS = 10000

type Action = Readonly<{ atMs: number; index: number }>

export function replayGame(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > MAX_REPLAY_BYTES) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!isRecord(parsed) || !hasExactKeys(parsed, ['version', 'boardCode', 'actions', 'endMs'])) return null
  if (parsed.version !== REPLAY_VERSION || typeof parsed.boardCode !== 'string') return null
  if (!isTime(parsed.endMs) || !Array.isArray(parsed.actions) || parsed.actions.length > MAX_ACTIONS) return null
  const board = parseBoardCode(parsed.boardCode)
  if (board === null) return null
  const actions: Action[] = []
  let previousTime = 0
  for (const item of parsed.actions) {
    if (!isRecord(item) || !hasExactKeys(item, ['atMs', 'index'])) return null
    if (!isTime(item.atMs) || !isIndex(item.index, board.deck.length)) return null
    if (item.atMs < previousTime) return null
    actions.push(Object.freeze({ atMs: item.atMs, index: item.index }))
    previousTime = item.atMs
  }
  const lastAction = actions[actions.length - 1]
  if (lastAction !== undefined && parsed.endMs < lastAction.atMs) return null
  return runActions(parsed.boardCode, actions, parsed.endMs)
}

function runActions(boardCode: string, actions: readonly Action[], endMs: number): GameState | null {
  let state = createGame(boardCode)
  if (state === null) return null
  let previousTime = actions[0]?.atMs ?? 0
  for (const action of actions) {
    const elapsed = action.atMs - previousTime
    state = advanceGame(state, elapsed)
    state = activateCard(state, action.index)
    previousTime = action.atMs
  }
  return advanceGame(state, endMs - previousTime)
}


function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasExactKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(record)
  return actual.length === keys.length && keys.every((key) => Object.hasOwn(record, key))
}

function isIndex(value: unknown, length: number): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value < length
}

function isTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
}
# Neon Pairs
Neon Pairs is a browser memory game that asks you to find every matching pair.

Read [Neon Pairs game specification and document map](docs/README.md) to build the game.

Follow the requirements in docs/ for this project.
