function newSeed(): number {
  try {
    const value = new Uint32Array(1)
    globalThis.crypto.getRandomValues(value)
    return (value[0] ?? 0) % MAX_SEED + 1
  } catch {
    return Math.floor(Math.random() * MAX_SEED) + 1
  }
}

