import { MAX_SEED, type BoardSize } from '../model.ts'

export function freshBoardCode(size: BoardSize, previousCode?: string): string {
  let seed = newSeed()
  while (`np1-${size}-${seed}` === previousCode) seed = newSeed()
  return `np1-${size}-${seed}`
}

